// Resolution Hub no-approval workflow update 3.0.1
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let me=null,csrf='',workspace='',page='Dashboard',adminTab='Overview',files=[],queue=[],sources=[],selected=0,conversationId=null,messages=[],editing=null,offset=0,query='',filter='',settingsCache=null;
const status=s=>{$('status').textContent=s;};
const has=p=>me?.user.permissions.includes(p);
const base=()=>'/workspaces/'+encodeURIComponent(workspace);
const wsName=()=>me?.workspaces.find(w=>w.id===workspace)?.name||workspace;
let dark=localStorage.getItem('rh-theme')!=='light';
function theme(){document.documentElement.classList.toggle('light',!dark);localStorage.setItem('rh-theme',dark?'dark':'light');}
theme();
function run(fn){return async e=>{const b=e?.currentTarget;if(b?.tagName==='BUTTON')b.disabled=true;status('');try{await fn(e);}catch(err){status(err.message);}finally{if(b?.tagName==='BUTTON')b.disabled=false;}};}
async function api(path,method='GET',body=null){const o={method,credentials:'same-origin',headers:{}};if(!['GET','HEAD'].includes(method))o.headers['X-CSRF-Token']=csrf;if(body instanceof FormData)o.body=body;else if(body!==null){o.headers['Content-Type']='application/json';o.body=JSON.stringify(body);}const r=await fetch('/api'+path,o);let d;try{d=await r.json();}catch{throw Error('Server returned an unexpected response');}if(!r.ok){if(r.status===401&&path!='/auth/login'){me=null;login();}throw Error(typeof d.detail==='string'?d.detail:JSON.stringify(d.detail));}return d;}
const on=(id,fn)=>{const e=$(id);if(e)e.addEventListener('click',run(fn));};
const btn=(id,label,primary=false)=>`<button type="button" id="${id}" class="${primary?'primary':''}">${label}</button>`;
function heading(k,h,s,action=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${h}</h1><div class="muted">${s}</div></div>${action}</div>`;}
function modal(title,body){$('modal-body').innerHTML=`<h2>${esc(title)}</h2>${body}`;$('modal').showModal();}
$('modal-close').onclick=()=>{$('modal').close();$('modal-body').textContent='';};
async function branding(){const b=await api('/branding');$('footer-name').textContent=b.instance_name;$('logo').innerHTML=b.logo?'<img src="/api/logo" alt="Instance logo">':'RH';}
async function refreshMe(){me=await api('/me');csrf=me.csrf;if(!me.workspaces.some(w=>w.id===workspace))workspace=me.workspaces[0]?.id||'';}
function navigation(){let views=['Dashboard'];if(has('solve'))views.push('Solve Issue');if(has('knowledge.create'))views.push('Add Knowledge');if(has('knowledge.read'))views.push('Library');if(has('solve'))views.push('History');if(has('users.manage'))views.push('Users');if(['roles.manage','settings.manage','audit.read','maintenance.manage'].some(has))views.push('Admin');views.push('Guide');$('nav').innerHTML=views.map(v=>`<button type="button" class="pill ${v===page?'active':''}" data-page="${v}">${v}</button>`).join('')+btn('theme',dark?'☀ Light':'☾ Dark')+btn('profile',esc(me.user.display_name))+btn('logout','Logout');document.querySelectorAll('[data-page]').forEach(b=>b.onclick=run(async()=>{page=b.dataset.page;offset=0;await render();}));on('theme',()=>{dark=!dark;theme();navigation();});on('profile',async()=>{page='Profile';await render();});on('logout',async()=>{await api('/auth/logout','POST');me=null;csrf='';files=[];messages=[];conversationId=null;login();});$('context').innerHTML=`<div class="context"><div class="row"><span class="eyebrow">${esc(me.instance_name)}</span><span class="muted">/</span><select id="workspace" aria-label="Workspace">${me.workspaces.map(w=>`<option value="${esc(w.id)}" ${w.id===workspace?'selected':''}>${esc(w.name)}</option>`).join('')}</select></div><div class="row"><span class="badge">${esc(me.provider)} mode</span><small>${esc(me.user.role)}</small></div></div>`;$('workspace').onchange=run(async()=>{workspace=$('workspace').value;files=[];queue=[];messages=[];conversationId=null;editing=null;offset=0;await render();});}
function login(){page='Dashboard';$('context').innerHTML='';$('nav').innerHTML=btn('theme',dark?'Light mode':'Dark mode');on('theme',()=>{dark=!dark;theme();login();});$('main').innerHTML=`<div class="login">${heading('WELCOME BACK','Your team’s knowledge.','Sign in to your Resolution Hub instance.')}<section class="card"><form id="login-form"><label for="username">Username</label><input id="username" autocomplete="username" required maxlength="80"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required maxlength="128"><p><button type="submit" class="primary">Sign in</button> ${btn('forgot','Forgot password?')}</p></form><small>Accounts are managed by your instance administrator. No public self-registration.</small></section></div>`;$('login-form').onsubmit=run(async e=>{e.preventDefault();const r=await api('/auth/login','POST',{username:$('username').value,password:$('password').value});csrf=r.csrf;$('password').value='';await refreshMe();await render();});on('forgot',()=>forgotForm());}
function forgotForm(){
  modal('Reset your password',`<p class="muted">Enter your username. If an email address is registered for your account, we will send a password reset link.</p><form id="forgot-form"><label for="forgot-username">Username</label><input id="forgot-username" autocomplete="username" required maxlength="80"><p><button type="submit" class="primary">Send reset link</button></p></form><small>No automated email is sent if your account has no registered address. Contact your administrator if you do not receive one.</small>`);
  $('forgot-form').onsubmit=run(async e=>{e.preventDefault();const r=await api('/auth/forgot','POST',{username:$('forgot-username').value});$('modal-body').innerHTML=`<h2>Check your email</h2><p>${esc(r.notice)}</p><p class="muted">The link expires shortly and can be used once.</p>`;});
}
// Token-based reset page, reached via the ?reset=TOKEN link in the reset email.
function resetPage(token){
  page='Reset';$('context').innerHTML='';$('nav').innerHTML=btn('theme',dark?'Light mode':'Dark mode');on('theme',()=>{dark=!dark;theme();resetPage(token);});
  $('main').innerHTML=`<div class="login">${heading('ACCOUNT RECOVERY','Choose a new password.','Set a new password for your Resolution Hub account.')}<section class="card"><form id="reset-form"><label for="reset-new">New password</label><input id="reset-new" type="password" autocomplete="new-password" minlength="15" maxlength="128" required><label for="reset-confirm">Confirm new password</label><input id="reset-confirm" type="password" autocomplete="new-password" required><p class="muted">Use 15–128 characters. All existing sessions are revoked.</p><button type="submit" class="primary">Set new password</button></form></section></div>`;
  $('reset-form').onsubmit=run(async e=>{e.preventDefault();if($('reset-new').value!==$('reset-confirm').value)throw Error('New passwords do not match');await api('/auth/reset','POST',{token,new_password:$('reset-new').value});history.replaceState(null,'',location.pathname);me=null;csrf='';login();status('Password reset. Sign in with your new password.');});
}
async function render(){status('');if(!me){login();return;}navigation();if(me.user.must_change){passwordPage(true);return;}if(!workspace){$('main').innerHTML='<section class="card">No workspace access. Contact your administrator.</section>';return;}const routes={'Dashboard':dashboard,'Add Knowledge':knowledge,'Library':library,'Solve Issue':solve,'History':history,'Users':users,'Admin':admin,'Guide':guide,'Profile':profile,'Import Review':importReview,'Knowledge Detail':detail};await (routes[page]||dashboard)();}
function passwordPage(forced=false){$('main').innerHTML=`<div class="login card"><div class="eyebrow">ACCOUNT SECURITY</div><h1>${forced?'Change temporary password':'Change password'}</h1><p class="muted">Use 15–128 characters. All sessions will be revoked after changing it.</p><form id="password-form"><label>Current password<input id="current-password" type="password" autocomplete="current-password" required></label><label>New password<input id="new-password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label>Confirm new password<input id="confirm-password" type="password" autocomplete="new-password" required></label><button class="primary" type="submit">Change password</button></form></div>`;$('password-form').onsubmit=run(async e=>{e.preventDefault();if($('new-password').value!==$('confirm-password').value)throw Error('New passwords do not match');await api('/auth/password','POST',{current_password:$('current-password').value,new_password:$('new-password').value});me=null;csrf='';login();status('Password changed. Sign in with your new password.');});}
async function dashboard(){const d=await api(base()+'/dashboard');const c=d.counts;const stats=[[BOOKS_ICON,Object.values(c).reduce((a,b)=>a+b,0),'Knowledge entries','Library'],['✓',c.published||0,'Searchable resolutions','Library'],['◷',(c.draft||0)+(c.unresolved||0),'Unresolved / legacy drafts','Library'],['↗',d.conversations,'Your investigations','History']];$('main').innerHTML=heading('WORKSPACE OVERVIEW','Knowledge into action',`A focused view of ${esc(wsName())} knowledge and investigations.`,has('solve')?btn('new-case','＋ New investigation',true):'')+`<div class="stats">${stats.map((s,i)=>`<button class="stat" data-stat="${i}" type="button"><span class="icon">${s[0]}</span><span><strong>${s[1]}</strong><small>${s[2]}</small></span></button>`).join('')}</div><div class="grid"><section class="card"><h2>Bring an issue. Find a path forward.</h2><p class="muted">Paste an email, attach screenshots and continue the investigation.</p>${has('solve')?btn('dash-solve','Open Solve Issue',true):''}</section><section class="card"><h2>Already have the solution?</h2><p class="muted">Import a document with both the issue and resolution. Review the extracted pairs without retyping.</p>${has('knowledge.create')?btn('dash-add','Add knowledge'):''}</section></div><section class="card"><h2>Recent workspace knowledge</h2><div id="recent"></div></section>`;if(has('knowledge.read'))$('recent').innerHTML=noteTable((await api(base()+'/knowledge')).slice(0,5));else $('recent').textContent='Knowledge access is not granted to this role.';wireDetails();for(const id of ['new-case','dash-solve'])on(id,async()=>{page='Solve Issue';await render();});on('dash-add',async()=>{page='Add Knowledge';editing=null;files=[];await render();});document.querySelectorAll('[data-stat]').forEach(b=>b.onclick=run(async()=>{const dest=stats[+b.dataset.stat][3];if(dest==='Library'&&!has('knowledge.read'))return;if(dest==='History'&&!has('solve'))return;page=dest;await render();}));}
function noteTable(rows){return `<div class="tablewrap"><table class="list"><thead><tr><th>Issue / knowledge</th><th>Status</th><th>Environment/Server</th><th>Action</th></tr></thead><tbody>${rows.map(n=>`<tr><td>${esc(n.issue_text.slice(0,120)||'Image-based issue')}</td><td><span class="badge ${n.status==='published'?'green':'amber'}">${esc(n.status)}</span></td><td>${esc(n.environment||'—')}</td><td><button type="button" class="link" data-detail="${n.id}">Open</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':'<div class="empty">No knowledge entries yet.</div>'}`;}
let detailId=null;
function wireDetails(){document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=run(async()=>{detailId=b.dataset.detail;page='Knowledge Detail';await render();}));}
function editor(id,placeholder,value=''){return `<div class="toolbar"><button type="button" data-format="bold" data-editor="${id}" aria-label="Bold">B</button><button type="button" data-format="italic" data-editor="${id}" aria-label="Italic">I</button><button type="button" data-format="insertUnorderedList" data-editor="${id}">List</button><small>Rich text · Remote images blocked</small></div><div id="${id}" class="editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="${esc(placeholder)}" data-placeholder="${esc(placeholder)}">${value}</div>`;}
// Paste only allowlisted DOM. The backend sanitizes again before storage.
function safePaste(html){const doc=new DOMParser().parseFromString(html,'text/html'),allowed=new Set(['P','BR','B','STRONG','I','EM','U','S','UL','OL','LI','TABLE','TBODY','THEAD','TR','TD','TH','BLOCKQUOTE','DIV','SPAN','PRE','CODE','H1','H2','H3','HR']);function clean(n){if(n.nodeType===3)return document.createTextNode(n.textContent);if(n.nodeType!==1)return document.createDocumentFragment();if(['SCRIPT','STYLE','IFRAME','OBJECT','IMG','SVG','MATH','LINK','META'].includes(n.tagName))return document.createDocumentFragment();const out=allowed.has(n.tagName)?document.createElement(n.tagName.toLowerCase()):document.createDocumentFragment();for(const c of n.childNodes)out.appendChild(clean(c));return out;}const box=document.createElement('div');for(const n of doc.body.childNodes)box.appendChild(clean(n));return box.innerHTML;}
function wireEditors(){document.querySelectorAll('[data-format]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>{$(b.dataset.editor).focus();document.execCommand(b.dataset.format,false,null);};});document.querySelectorAll('[contenteditable]').forEach(ed=>ed.addEventListener('paste',async e=>{e.preventDefault();const d=e.clipboardData;const html=d.getData('text/html');document.execCommand(html?'insertHTML':'insertText',false,html?safePaste(html):d.getData('text/plain'));for(const item of [...d.items].filter(i=>i.kind==='file'&&/^image\/(png|jpeg|webp)$/.test(i.type)).slice(0,4)){try{await attach(item.getAsFile(),ed.id);}catch(err){status(err.message);}}}));}
function uploadBox(){return `<div class="upload"><div class="row">${btn('upload','＋ Upload email / files')}${page==='Add Knowledge'?btn('extract','Review extracted issue–resolution pairs'):''}</div><small>EML, MSG, text PDF, DOCX, TXT, MD, LOG, CSV, JSON and images. Extraction warnings are shown; exact source layout is not guaranteed.</small><input id="file-input" type="file" multiple class="hidden" accept=".eml,.msg,.pdf,.docx,.txt,.md,.log,.csv,.json,.png,.jpg,.jpeg,.webp"><div id="chips"></div></div>`;}
function chips(){if(!$('chips'))return;$('chips').innerHTML=files.map((a,i)=>`<span class="chip"><a href="/api/assets/${a.id}/download">${esc(a.name)}</a><button type="button" data-remove="${i}" aria-label="Remove attachment">×</button></span>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{files.splice(+b.dataset.remove,1);chips();});}
async function attach(file,editorId){const selectedWorkspace=workspace;const f=new FormData();f.append('file',file);status('Uploading and extracting…');const a=await api(base()+'/assets','POST',f);if(workspace!==selectedWorkspace)return;files.push(a);chips();const ed=$(editorId);if(ed){const div=document.createElement('div');div.innerHTML=a.html;ed.appendChild(div);}status(a.warnings.length?a.warnings.join('\n'):'File extracted. Review the content before saving or sending.');return a;}
function wireUploads(editorId){chips();on('upload',()=>$('file-input').click());$('file-input').onchange=run(async e=>{for(const f of [...e.target.files].slice(0,10))await attach(f,editorId);});on('extract',async()=>{if(!files.length)throw Error('Upload a file first');await extractImport(false);});}
async function extractImport(useAI){const r=await api(base()+'/extract','POST',{asset_ids:files.map(a=>a.id),use_ai:useAI});queue=r.pairs;sources=r.sources;selected=0;if(!queue.length){status(r.warnings.join('\n'));return;}page='Import Review';await render();}
async function knowledge(){if(!has('knowledge.create')&&!editing)throw Error('Knowledge creation not permitted');$('main').innerHTML=heading('KNOWLEDGE CAPTURE',editing?'Edit knowledge':'An issue. A resolution. Nothing extra.','Write directly, paste a formatted email, or import a document containing both.')+`<div class="banner">Complete document? Upload → review extracted pairs → save knowledge. No resolution retyping required. Missing solutions remain unresolved.</div><section class="card"><label>1 · Issue / Email / Extracted Content</label>${editor('issue','Paste the whole email, describe the issue or import files…',editing?.issue_html||'')}${uploadBox()}<label>2 · Resolution</label>${editor('resolution','Write the confirmed resolution, or extract it from the uploaded document…',editing?.resolution_html||'')}<details><summary>Optional context</summary><label for="environment">Environment/Server</label><input id="environment" value="${esc(editing?.environment||'')}"></details><div class="row">${btn('save-knowledge','Save knowledge',true)}${btn('clear-knowledge','Clear form')}</div><small>No Type, Category, Review Due or Version fields. Versions and audit remain internal.</small></section>`;wireEditors();wireUploads('issue');on('clear-knowledge',async()=>{editing=null;files=[];await knowledge();});on('save-knowledge',async()=>{const body={issue_html:$('issue').innerHTML,resolution_html:$('resolution').innerHTML,environment:$('environment').value,asset_ids:files.map(a=>a.id),expected_version:editing?.version||null};await api(editing?base()+'/knowledge/'+editing.id:base()+'/knowledge',editing?'PUT':'POST',body);editing=null;files=[];page='Library';await render();status('Saved. Entries with a resolution are searchable immediately; empty resolutions remain unresolved.');});}
function capturePair(){const p=queue[selected];if(!p)return;if($('pair-issue'))p.issue_html=$('pair-issue').innerHTML;if($('pair-resolution'))p.resolution_html=$('pair-resolution').innerHTML;if($('pair-confirm'))p.confirmed=$('pair-confirm').checked;}
async function importReview(){if(!queue.length){page='Add Knowledge';await render();return;}const p=queue[selected];$('main').innerHTML=heading('IMPORT & REVIEW','Both fields, extracted together.','Compare source and extracted pairings. Never treat an inferred fix as confirmed.',btn('back-add','Back to Add Knowledge'))+`<div class="steps"><span>1 · Upload</span><span>2 · Review ${queue.length} case(s)</span><span>3 · Save knowledge</span></div><div class="split"><section class="card"><h2>Case ${selected+1} of ${queue.length}</h2><span class="badge">${esc(p.method)} extraction</span><label>Issue / Email / Extracted Content</label>${editor('pair-issue','Extracted issue',p.issue_html)}<label>Resolution</label>${editor('pair-resolution','Leave blank for an unresolved draft',p.resolution_html)}<label class="row"><input type="checkbox" id="pair-confirm" ${p.confirmed?'checked':''}>I checked this pairing against the source</label><div class="row">${btn('pair-prev','Previous case')}${btn('pair-next','Next case')}</div><div class="banner">${p.warnings.map(esc).join('<br>')||'Verify that the resolution is documented and belongs to this issue.'}</div></section><section class="card"><h2>Original extracted source</h2>${sources.map(s=>`<details open><summary>${esc(s.name)}</summary><div class="rich">${s.html}</div><small>${s.warnings.map(esc).join('<br>')}</small></details>`).join('')}<h3>Review queue</h3>${queue.map((p,i)=>`<button type="button" data-pair="${i}" class="pill ${i===selected?'active':''}">Case ${i+1}${p.confirmed?' ✓':''}</button>`).join('')}<p><small>AI extraction is optional and must be enabled by an administrator. Source comparison remains mandatory.</small></p>${btn('ai-extract','Try approved AI extraction')}</section></div><section class="card row">${btn('import-save','Save reviewed cases',true)}${btn('import-cancel','Cancel import')}</section>`;wireEditors();on('back-add',async()=>{capturePair();page='Add Knowledge';await render();});on('pair-prev',async()=>{capturePair();selected=Math.max(0,selected-1);await importReview();});on('pair-next',async()=>{capturePair();selected=Math.min(queue.length-1,selected+1);await importReview();});document.querySelectorAll('[data-pair]').forEach(b=>b.onclick=run(async()=>{capturePair();selected=+b.dataset.pair;await importReview();}));on('ai-extract',async()=>{if(!confirm('Send extracted text to the configured approved AI provider? Unsaved pair edits will be replaced.'))return;await extractImport(true);});on('import-cancel',async()=>{queue=[];page='Add Knowledge';await render();});on('import-save',async()=>{capturePair();const ready=queue.filter(p=>p.confirmed);if(!ready.length)throw Error('Review and confirm at least one pairing');const pairs=ready.map(p=>({issue_html:p.issue_html,resolution_html:p.resolution_html,environment:'',asset_ids:p.asset_ids,confirmed:true}));const r=await api(base()+'/import','POST',{pairs});queue=queue.filter(p=>!p.confirmed);files=[];page='Library';await render();status(`${r.saved.length} case(s) saved as searchable/unresolved records. Unreviewed cases remain in the queue.`);});}
async function library(){const rows=await api(base()+'/knowledge?q='+encodeURIComponent(query)+'&status='+encodeURIComponent(filter)+'&offset='+offset);$('main').innerHTML=heading('REUSABLE TEAM KNOWLEDGE','Knowledge library','Issue–resolution pairs, source context and review status.',has('knowledge.create')?btn('library-add','＋ Add knowledge',true):'')+`<section class="card"><div class="grid"><div><label>Search everything<input id="query" value="${esc(query)}" placeholder="Issue, resolution or phrase"></label></div><div><label>Status<select id="filter">${['','published','draft','unresolved','archived'].map(s=>`<option value="${s}" ${s===filter?'selected':''}>${s||'All'}</option>`).join('')}</select></label></div></div><div class="row">${btn('apply','Apply',true)}${btn('reset-filter','Reset')}</div></section><section class="card"><h2>Knowledge entries</h2>${noteTable(rows)}<div class="row">${btn('previous','Previous')}${btn('next','Next')}</div></section>`;wireDetails();on('library-add',async()=>{editing=null;files=[];page='Add Knowledge';await render();});on('apply',async()=>{query=$('query').value;filter=$('filter').value;offset=0;await library();});on('reset-filter',async()=>{query='';filter='';offset=0;await library();});on('previous',async()=>{offset=Math.max(0,offset-50);await library();});on('next',async()=>{offset+=50;await library();});}
async function detail(){const k=await api('/knowledge/'+detailId);$('main').innerHTML=heading('KNOWLEDGE DETAIL','Issue and documented resolution','Saved resolutions are searchable immediately. No second-person approval is required.',btn('back-library','Back to library'))+`<section class="card"><span class="badge ${k.status==='published'?'green':'amber'}">${esc(k.status)}</span><h2>Issue</h2><div class="rich">${k.issue_html}</div><div class="sectionline"></div><h2>Resolution</h2><div class="rich">${k.resolution_text?k.resolution_html:'No documented resolution. Excluded from confirmed-fix recommendations.'}</div><p><small>Environment/Server: ${esc(k.environment||'Not provided')}</small></p><h3>Source attachments</h3>${k.assets.map(a=>`<span class="chip"><a href="/api/assets/${a.id}/download">${esc(a.name)}</a></span>`).join('')}<div class="row">${has('knowledge.edit')?btn('edit-note','Edit'):''}${has('knowledge.review')?btn('archive','Archive'):''}${has('solve')?btn('investigate','Investigate related issue'):''}</div><details><summary>Internal traceability</summary>${btn('versions','Load version history')}<div id="version-data"></div></details></section>`;on('back-library',async()=>{page='Library';await render();});on('edit-note',async()=>{editing=k;files=k.assets;page='Add Knowledge';await render();});for(const [id,s] of [['archive','archived']])on(id,async()=>{const note=prompt('Review rationale (required)');if(!note)return;await api('/knowledge/'+k.id+'/review','POST',{expected_version:k.version,status:s,note});await detail();status('Review saved.');});on('versions',async()=>{$('version-data').innerHTML='<pre>'+esc(JSON.stringify(await api('/knowledge/'+k.id+'/versions'),null,2))+'</pre>';});on('investigate',async()=>{conversationId=null;messages=[];page='Solve Issue';await render();$('chat-input').textContent=k.issue_text;});}
async function solve(){
  if(conversationId){const r=await api('/conversations/'+conversationId);messages=r.messages;}
  const last=messages.filter(m=>m.role==='assistant').at(-1);
  const evidence=last?JSON.parse(last.sources):[];
  const hasResolution=!!last;
  const firstAnswer=messages.filter(m=>m.role==='assistant')[0];
  const canCreate=has('knowledge.create');
  // Left pane: original issue submission + latest advisory resolution + evidence.
  // Right pane: ChatGPT/Gemini-style follow-up assistant, active once a resolution exists.
  const leftBody=hasResolution
    ? `<section class="card"><div class="row" style="justify-content:space-between"><h2>Latest advisory resolution</h2><span class="badge">${esc(last.mode)} mode</span></div><div class="rich">${last.html}</div><div class="row">${btn('like-last','Useful')}${btn('dislike-last','Not useful')}${canCreate?btn('capture-resolution','Edit & save as knowledge'):''}</div><small class="muted">Advisory only. Validate applicability and obtain required approval before changes. Use the assistant on the right to ask follow-up questions in the same investigation.</small></section>
       <section class="card"><h2>Refine the original issue</h2><label>Add more context, a new email or images to the same investigation</label>${editor('chat-input','Add details, paste another email or attach images…')}${uploadBox()}<div class="row">${btn('send','Add to investigation',true)}</div><small>This continues the same conversation. For quick questions use the assistant panel.</small></section>`
    : `<section class="card"><label>Issue, email or question</label>${editor('chat-input','Paste an email with formatting, attach images or describe the issue…')}${uploadBox()}<div class="row">${btn('send','Get resolution',true)}${canCreate?btn('capture-resolution','Edit answer & save knowledge'):''}</div><small>Images require enabled OCR or an approved vision-capable model. Extraction limitations are reported.</small></section>`;
  const panel=hasResolution
    ? `<div class="assistant-panel"><div class="assistant-head"><div class="assistant-avatar">${AI_ICON}</div><div><h2>Follow-up assistant</h2><div class="muted">Same investigation · advisory</div></div><span class="assistant-dot" title="Active"></span></div><div class="assistant-log" id="followup-log">${chatMsgs()}</div><div class="assistant-compose"><div class="assistant-chips">${['What are the risks?','How do I validate this?','What if that does not work?'].map(q=>`<button type="button" data-suggest="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="assistant-inputwrap"><textarea id="followup-input" rows="1" placeholder="Ask a follow-up question…" aria-label="Follow-up question" maxlength="4000"></textarea><button type="button" id="followup-send" class="primary assistant-send" aria-label="Send follow-up">→</button></div><div class="assistant-hint">Enter to send · Shift+Enter for a new line. Answers are advisory, not verified fixes.</div></div></div>`
    : `<div class="assistant-panel"><div class="assistant-head"><div class="assistant-avatar">${AI_ICON}</div><div><h2>Follow-up assistant</h2><div class="muted">Waiting for first resolution</div></div><span class="assistant-dot idle" title="Idle"></span></div><div class="assistant-locked"><div class="big">Follow-up assistant</div><p>Submit your issue on the left to get the first resolution.</p><p class="muted">This panel then becomes a conversational assistant for follow-up questions about the same issue, keeping the full investigation in one thread.</p></div></div>`;
  const evidenceBlock=`<details class="assistant-evidence"><summary>Evidence · ${evidence.length} source(s) · ${esc(wsName())}</summary><div class="assistant-evidence-body"><p class="muted">Searchable resolutions only. Similarity is not proof of the same root cause.</p>${evidence.map(s=>`<details><summary>${esc(s.issue.slice(0,90))}</summary><small>${esc(s.id)}</small><p>${esc(s.resolution)}</p></details>`).join('')||'<p class="muted">Evidence appears here after a matching response.</p>'}</div></details>`;
    $('main').innerHTML=heading('AI-ASSISTED INVESTIGATION','Resolve. Ask. Continue.','Email context, images, evidence and follow-up questions in one conversation.',btn('new-chat','＋ New conversation'))
      +`<div class="split"><div>${leftBody}</div><aside class="assistant-aside">${panel}${evidenceBlock}</aside></div>`;
  wireEditors();wireUploads('chat-input');
  on('new-chat',async()=>{conversationId=null;messages=[];files=[];await solve();});
  on('send',async()=>{await sendChat($('chat-input').innerHTML,files.map(a=>a.id));});
  on('capture-resolution',async()=>{const a=messages.filter(m=>m.role==='assistant').at(-1);if(!a)throw Error('Generate an answer first, or add knowledge manually.');await prepareAnswerCorrection(a.id);});
  on('like-last',async()=>{if(last){await api('/messages/'+last.id+'/feedback','POST',{useful:true});status('Feedback saved.');}});
  on('dislike-last',async()=>{if(last){await api('/messages/'+last.id+'/feedback','POST',{useful:false});status('Feedback saved.');}});
  // Follow-up assistant panel wiring.
  const logEl=$('followup-log');if(logEl)logEl.scrollTop=logEl.scrollHeight;
  const input=$('followup-input');
  if(input){
    const grow=()=>{input.style.height='auto';input.style.height=Math.min(input.scrollHeight,140)+'px';};
    input.addEventListener('input',grow);
    input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('followup-send').click();}});
    setTimeout(()=>input.focus(),0);
  }
  document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{if(input){input.value=b.dataset.suggest;input.focus();}});
  on('followup-send',async()=>{await sendFollowup();});
  document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=run(async()=>{await api('/messages/'+b.dataset.feedback+'/feedback','POST',{useful:b.dataset.useful==='true'});status('Feedback saved.');}));
  document.querySelectorAll('[data-correct-answer]').forEach(b=>b.onclick=run(async()=>prepareAnswerCorrection(b.dataset.correctAnswer)));
}
// Render conversation history as ChatGPT-style bubbles for the follow-up panel.
// Inline AI "sparkle" glyph used for the assistant avatars (crisp, theme-colored).
const AI_ICON='<svg viewBox="0 0 24 24" width="17" height="17" fill="currentColor" aria-hidden="true" focusable="false"><path d="M12 2.2l1.9 4.9 4.9 1.9-4.9 1.9L12 15.8l-1.9-4.9L5.2 9l4.9-1.9L12 2.2z"/><path d="M18.5 14.5l.9 2.3 2.3.9-2.3.9-.9 2.3-.9-2.3-2.3-.9 2.3-.9.9-2.3z"/></svg>';
// Inline "books" glyph for the Knowledge entries stat (inherits accent/white via currentColor).
const BOOKS_ICON='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M4 5.5A1.5 1.5 0 0 1 5.5 4H10a2 2 0 0 1 2 2v13a2 2 0 0 0-2-2H4.5A.5.5 0 0 1 4 16.5z"/><path d="M20 5.5A1.5 1.5 0 0 0 18.5 4H14a2 2 0 0 0-2 2v13a2 2 0 0 1 2-2h5.5a.5.5 0 0 0 .5-.5z"/></svg>';
function chatMsgs(){
  return messages.map(m=>{
    const mine=m.role==='user';
    const acts=(!mine&&has('knowledge.create'))?`<div class="act"><button type="button" data-feedback="${m.id}" data-useful="true">Useful</button><button type="button" data-feedback="${m.id}" data-useful="false">Not useful</button><button type="button" data-correct-answer="${m.id}">Save as knowledge</button></div>`:(!mine?`<div class="act"><button type="button" data-feedback="${m.id}" data-useful="true">Useful</button><button type="button" data-feedback="${m.id}" data-useful="false">Not useful</button></div>`:'');
    return `<div class="msg ${mine?'me':'bot'}"><div class="av">${mine?'You':AI_ICON}</div><div class="body"><span class="meta">${mine?'You':esc(m.mode)+' · advisory'}</span><div class="rich">${m.html}</div>${acts}</div></div>`;
  }).join('');
}
// Shared send for the left pane (full editor) and panel. Shows a typing indicator.
async function sendChat(html,assetIds){
  const selectedWs=workspace;status('Analysing the issue…');
  const r=await api(base()+'/chat','POST',{html,asset_ids:assetIds,conversation_id:conversationId});
  if(workspace!==selectedWs||page!=='Solve Issue')return;
  conversationId=r.conversation_id;files=[];await solve();status(r.warnings.join('\n'));
}
async function sendFollowup(){
  const input=$('followup-input');if(!input)return;
  const q=input.value.trim();if(!q)return;
  const selectedWs=workspace;input.disabled=true;$('followup-send').disabled=true;
  const log=$('followup-log');
  if(log){
    log.insertAdjacentHTML('beforeend',`<div class="msg me"><div class="av">You</div><div class="body"><div class="rich">${esc(q).replace(/\n/g,'<br>')}</div></div></div>`);
    log.insertAdjacentHTML('beforeend',`<div class="msg bot" id="followup-typing"><div class="av">${AI_ICON}</div><div class="body"><span class="typing"><span></span><span></span><span></span></span></div></div>`);
    log.scrollTop=log.scrollHeight;
  }
  status('');
  try{
    const r=await api(base()+'/chat','POST',{html:'<p>'+esc(q).replace(/\n/g,'<br>')+'</p>',asset_ids:[],conversation_id:conversationId});
    if(workspace!==selectedWs||page!=='Solve Issue')return;
    conversationId=r.conversation_id;await solve();
    if(r.warnings&&r.warnings.length)status(r.warnings.join('\n'));
  }catch(err){
    $('followup-typing')?.remove();
    if(input){input.disabled=false;}$('followup-send')&&($('followup-send').disabled=false);
    status(err.message);
  }
}
async function history(){const rows=await api(base()+'/history?offset='+offset);$('main').innerHTML=heading('INVESTIGATION HISTORY','Pick up where you left off',`Your private investigations in ${esc(wsName())}.`)+`<section class="card">${rows.map(r=>`<div class="row" style="padding:15px 0;border-bottom:1px solid var(--line);justify-content:space-between"><div><strong>${esc(r.title)}</strong><br><small>${new Date(r.updated*1000).toLocaleString()}</small></div><button type="button" data-resume="${r.id}">Resume</button></div>`).join('')||'<div class="empty">No investigations yet.</div>'}<div class="row">${btn('previous','Previous')}${btn('next','Next')}</div></section>`;document.querySelectorAll('[data-resume]').forEach(b=>b.onclick=run(async()=>{conversationId=b.dataset.resume;files=[];page='Solve Issue';await render();}));on('previous',async()=>{offset=Math.max(0,offset-50);await history();});on('next',async()=>{offset+=50;await history();});}
async function users(){const [rows,roleData]=await Promise.all([api('/admin/users'),api('/admin/roles')]);const roleOptions=(role)=>roleData.roles.map(r=>`<option ${r.name===role?'selected':''}>${esc(r.name)}</option>`).join('');const wsChecks=(grants,id)=>`<div class="checks">${['*',...me.workspaces.map(w=>w.id)].map(w=>`<label><input type="checkbox" data-grant="${id}" value="${esc(w)}" ${grants.includes(w)?'checked':''}>${w==='*'?'All workspaces':esc(w)}</label>`).join('')}</div>`;$('main').innerHTML=heading('ACCESS MANAGEMENT','Users','Create accounts, assign roles, revoke sessions and manage workspace access.')+`<section class="card"><h2>Add user</h2><div class="grid"><div><label>Username<input id="new-username" maxlength="40"></label><label>Display name<input id="new-display" maxlength="80"></label><label>Email (for password reset)<input id="new-email" type="email" maxlength="200" placeholder="user@example.com"></label></div><div><label>Role<select id="new-role">${roleOptions('Engineer')}</select></label><label>Workspace access</label>${wsChecks([workspace],'new')}</div></div>${btn('add-user','Create account',true)}<small>Temporary password is shown once. Deliver it securely; first sign-in requires a change.</small></section><section class="card"><h2>Accounts (${rows.length})</h2><div class="tablewrap"><table class="list"><thead><tr><th>Username</th><th>Email</th><th>Role</th><th>Workspace access</th><th>Active</th><th>Actions</th></tr></thead><tbody>${rows.map((u,i)=>`<tr><td>${esc(u.username)}<br><small>${esc(u.display_name)}</small></td><td><input id="email-${i}" type="email" maxlength="200" aria-label="Email for ${esc(u.username)}" value="${esc(u.email||'')}" placeholder="—"></td><td><select id="role-${i}" aria-label="Role for ${esc(u.username)}">${roleOptions(u.role)}</select></td><td>${wsChecks(u.workspaces,String(i))}</td><td><input type="checkbox" id="active-${i}" aria-label="Active ${esc(u.username)}" ${u.active?'checked':''}></td><td><button type="button" data-user-save="${i}">Save access</button><button type="button" data-user-reset="${i}">Reset password</button><button type="button" data-user-revoke="${i}">Revoke sessions</button></td></tr>`).join('')}</tbody></table></div></section>`;const grants=id=>[...document.querySelectorAll(`[data-grant="${id}"]:checked`)].map(x=>x.value);on('add-user',async()=>{const r=await api('/admin/users','POST',{username:$('new-username').value,display_name:$('new-display').value,role:$('new-role').value,workspaces:grants('new'),email:$('new-email').value});await users();modal('Temporary password: shown once',`<p>${esc(r.notice)}</p><pre>${esc(r.temporary_password)}</pre>`);});document.querySelectorAll('[data-user-save]').forEach(b=>b.onclick=run(async()=>{const i=+b.dataset.userSave;await api('/admin/users/'+rows[i].id,'PATCH',{role:$('role-'+i).value,workspaces:grants(String(i)),active:$('active-'+i).checked,email:$('email-'+i).value});await users();status('Access updated; user sessions revoked.');}));document.querySelectorAll('[data-user-reset]').forEach(b=>b.onclick=run(async()=>{if(!confirm('Reset password and revoke all sessions for this account?'))return;const r=await api('/admin/users/'+rows[+b.dataset.userReset].id+'/reset-password','POST');modal('Temporary password: shown once',`<p>${esc(r.notice)}</p><pre>${esc(r.temporary_password)}</pre>`);}));document.querySelectorAll('[data-user-revoke]').forEach(b=>b.onclick=run(async()=>{await api('/admin/users/'+rows[+b.dataset.userRevoke].id+'/revoke','POST');status('Sessions revoked.');}));}
async function admin(){const tabs=['Overview'];if(has('roles.manage'))tabs.push('Roles & RBAC');tabs.push('Workspaces');if(has('settings.manage'))tabs.push('AI Provider','Branding','Security');if(has('knowledge.create'))tabs.push('Imports');if(has('audit.read'))tabs.push('Audit');if(has('maintenance.manage'))tabs.push('Backup & Retention');if(!tabs.includes(adminTab))adminTab='Overview';$('main').innerHTML=heading('INSTANCE ADMINISTRATION','Administrator console','One instance. Independent workspaces. Centralized controls.')+`<div class="tabs">${tabs.map(t=>`<button type="button" data-tab="${t}" class="${t===adminTab?'active':''}">${t}</button>`).join('')}</div><div id="admin-body"></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=run(async()=>{adminTab=b.dataset.tab;await admin();}));const el=$('admin-body');if(adminTab==='Overview'){el.innerHTML=`<div class="grid">${tabs.filter(t=>t!=='Overview').map(t=>`<section class="card"><h2>${t}</h2><p class="muted">Manage ${t.toLowerCase()} for this instance.</p><button type="button" data-open-tab="${t}">Open ${t}</button></section>`).join('')}${has('users.manage')?`<section class="card"><h2>Users</h2><p class="muted">Accounts, role assignments and workspace access.</p>${btn('admin-users','Open Users')}</section>`:''}</div>`;document.querySelectorAll('[data-open-tab]').forEach(b=>b.onclick=run(async()=>{adminTab=b.dataset.openTab;await admin();}));on('admin-users',async()=>{page='Users';await render();});}
else if(adminTab==='Roles & RBAC'){const d=await api('/admin/roles');el.innerHTML=`<div class="grid"><section class="card"><h2>Permission editor</h2><label>Role<select id="role-edit">${d.roles.map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></label><div class="checks" id="permissions"></div><div class="row">${btn('save-role','Save role',true)}${btn('delete-role','Delete role')}</div><small>Administrator is protected. Assigned roles cannot be deleted. Role changes revoke affected sessions.</small></section><section class="card"><h2>Create a role</h2><label>Role name<input id="role-name" maxlength="50"></label>${btn('create-role','Create role')}<p class="muted">Permissions and workspace grants are enforced independently by the backend. A role manager cannot grant permissions they do not hold.</p></section></div>`;function checks(){const r=d.roles.find(r=>r.name===$('role-edit').value);$('permissions').innerHTML=d.permissions.map(p=>`<label><input type="checkbox" data-permission="${p}" ${r.permissions.includes(p)?'checked':''} ${r.name==='Administrator'?'disabled':''}>${p}</label>`).join('');}checks();$('role-edit').onchange=checks;on('save-role',async()=>{await api('/admin/roles','PUT',{name:$('role-edit').value,permissions:[...document.querySelectorAll('[data-permission]:checked')].map(e=>e.dataset.permission)});await admin();status('Role saved; affected sessions revoked.');});on('create-role',async()=>{await api('/admin/roles','PUT',{name:$('role-name').value,permissions:['solve','knowledge.read']});await admin();status('Role created.');});on('delete-role',async()=>{if(confirm('Delete this unassigned role?')){await api('/admin/roles/'+encodeURIComponent($('role-edit').value),'DELETE');await admin();}});}
else if(adminTab==='Workspaces'){el.innerHTML=`<section class="card"><h2>Workspace boundaries</h2><p class="muted">LCM is the deployment identity, not a workspace. Other teams customize config/instance.json and deploy a separate instance/database.</p>${me.workspaces.map(w=>`<div class="row" style="padding:12px 0;border-bottom:1px solid var(--line)"><strong>${esc(w.name)}</strong><small>${esc(w.id)}</small><button type="button" data-open-workspace="${esc(w.id)}">Open workspace</button></div>`).join('')}<p class="muted">Workspace IDs are stable data keys. Change display names in deployment configuration and restart. User access is editable in Users.</p></section>`;document.querySelectorAll('[data-open-workspace]').forEach(b=>b.onclick=run(async()=>{workspace=b.dataset.openWorkspace;conversationId=null;files=[];page='Dashboard';await render();}));}
else if(['AI Provider','Security','Branding'].includes(adminTab)){const d=await api('/admin/settings');settingsCache=d;const s=d.settings;if(adminTab==='AI Provider'){el.innerHTML=`<section class="card"><h2>Approved AI connection</h2><span class="badge">${esc(s.provider)}</span><label>Provider<select id="provider">${['evidence','openai','ollama'].map(p=>`<option ${p===s.provider?'selected':''}>${p}</option>`).join('')}</select></label><label>Compatible API base URL<input id="base-url" value="${esc(s.base_url)}" placeholder="Approved endpoint including API version prefix"></label><label>Model / deployment identifier<input id="model" value="${esc(s.model)}"></label><label class="row"><input id="vision" type="checkbox" ${s.vision?'checked':''}>Enable image input (requires a vision-capable approved model)</label><label class="row"><input id="ai-extract" type="checkbox" ${s.ai_extract?'checked':''}>Enable AI-assisted issue/resolution extraction</label><p class="muted">API key is ${d.api_key_configured?'configured':'not configured'} in the server environment. Secrets are not editable or displayed here. External AI enabled server-side: ${d.server_external_ai}. Allowed hosts: ${esc(d.allowed_hosts||'none')}.</p><div class="row">${btn('provider-save','Save settings',true)}${btn('provider-test','Test saved connection')}</div><small>openai selects a compatible request format, including approved compatible services. No embedding calls are made in this release; retrieval uses local FTS5.</small></section>`;on('provider-save',async()=>{await saveSettings({...s,provider:$('provider').value,base_url:$('base-url').value,model:$('model').value,vision:$('vision').checked,ai_extract:$('ai-extract').checked});});on('provider-test',async()=>{const r=await api('/admin/ai-test','POST');modal('Connection result','<pre>'+esc(JSON.stringify(r,null,2))+'</pre>');});}
else if(adminTab==='Security'){el.innerHTML=`<section class="card"><h2>Session & upload policy</h2><div class="grid"><label>Idle timeout (minutes)<input id="idle" type="number" min="5" max="120" value="${s.idle_minutes}"></label><label>Absolute session duration (hours)<input id="absolute" type="number" min="1" max="48" value="${s.absolute_hours}"></label><label>Upload limit (MB)<input id="upload-mb" type="number" min="1" max="20" value="${s.upload_mb}"></label></div><label class="row"><input id="scan" type="checkbox" ${s.require_scan?'checked':''}>Require ClamAV scan before extraction</label><p class="muted">Server scan mode: ${esc(d.scan_mode)}. OCR enabled: ${d.ocr_enabled}. Production cannot disable required scanning. Secure cookies and allowed origins are server configuration.</p>${btn('security-save','Save policy',true)}<div class="banner">Password hashing, session revocation, CSRF checks and backend permissions are active. This is not a security certification. See docs/SECURITY.md before rollout.</div></section>`;on('security-save',async()=>{await saveSettings({...s,idle_minutes:Number($('idle').value),absolute_hours:Number($('absolute').value),upload_mb:Number($('upload-mb').value),require_scan:$('scan').checked});});}
else{el.innerHTML=`<section class="card"><h2>Instance branding</h2><label>Instance name<input id="brand-name" value="${esc(s.instance_name)}"></label>${btn('brand-save','Save name',true)}<label>Offline PNG logo<input id="logo-file" type="file" accept="image/png"></label><small>PNG under 2 MB. Re-encoded and stored locally on the application server.</small><div class="row">${btn('logo-upload','Upload logo')}${btn('logo-reset','Reset logo')}</div></section>`;on('brand-save',async()=>{await saveSettings({...s,instance_name:$('brand-name').value});await branding();});on('logo-upload',async()=>{const f=$('logo-file').files[0];if(!f)throw Error('Choose a PNG first');const form=new FormData();form.append('file',f);await api('/admin/logo','POST',form);await branding();status('Logo saved.');});on('logo-reset',async()=>{await api('/admin/logo','DELETE');await branding();status('Logo reset.');});}}
else if(adminTab==='Imports'){el.innerHTML=`<section class="card"><h2>Extraction review queue</h2><p>${queue.length} case(s) in this browser’s current review queue.</p><p class="muted">Source uploads are persisted securely. Unsaved pair edits remain in this tab only. Review each pairing before import.</p><div class="row">${btn('open-queue','Open review queue',true)}${btn('new-import','Start an import')}</div></section>`;on('open-queue',async()=>{if(!queue.length)throw Error('No pending cases. Upload a document in Add Knowledge first.');page='Import Review';await render();});on('new-import',async()=>{page='Add Knowledge';await render();});}
else if(adminTab==='Audit'){const rows=await api('/admin/audit?offset='+offset);el.innerHTML=`<section class="card"><h2>Audit events</h2><div class="tablewrap"><table class="list"><thead><tr><th>Action</th><th>Actor ID</th><th>Workspace</th><th>Time</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.action)}</td><td>${esc(r.actor)}</td><td>${esc(r.workspace)}</td><td>${new Date(r.created*1000).toLocaleString()}</td></tr>`).join('')}</tbody></table></div><div class="row">${btn('audit-prev','Previous')}${btn('audit-next','Next')}</div><small>Hash-linked database events are not immutable against a privileged database operator.</small></section>`;on('audit-prev',async()=>{offset=Math.max(0,offset-100);await admin();});on('audit-next',async()=>{offset+=100;await admin();});}
else{el.innerHTML=`<section class="card"><h2>Backup & retention</h2><p class="muted">Full backup is an operator CLI action: <code>python scripts/backup.py /secure/path/backup.db</code>. The database includes attachments. Back up logo.png and deployment configuration separately.</p><div class="row">${btn('export','Export knowledge JSON')}${btn('reindex','Rebuild search index')}${btn('purge','Purge expired investigation history')}</div><div class="banner">Knowledge export is not a full backup. Purge deletes only old conversations/messages/feedback, not knowledge, attachments, audit or backups. Restore verification is an operator responsibility.</div><div id="maintenance-result"></div></section>`;if(has('settings.manage')){const d=await api('/admin/settings');settingsCache=d;el.innerHTML+=`<section class="card"><label>Investigation retention (days)<input id="retention" type="number" min="1" max="3650" value="${d.settings.retention_days}"></label>${btn('retention-save','Save retention',true)}</section>`;on('retention-save',async()=>saveSettings({...d.settings,retention_days:Number($('retention').value)}));}on('export',async()=>{const d=await api('/admin/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='resolution-hub-knowledge.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});on('reindex',async()=>{$('maintenance-result').innerHTML='<pre>'+esc(JSON.stringify(await api('/admin/reindex','POST'),null,2))+'</pre>';});on('purge',async()=>{if(confirm('Permanently delete investigation history older than the configured retention period?'))$('maintenance-result').innerHTML='<pre>'+esc(JSON.stringify(await api('/admin/purge-history','POST'),null,2))+'</pre>';});}}
async function saveSettings(s){await api('/admin/settings','PUT',{...s,expected_version:settingsCache.version});await refreshMe();await admin();navigation();status('Settings saved. Secrets and server-side allowlists remain environment-managed.');}
function guide(){$('main').innerHTML=heading('HELP & WALKTHROUGH','A simpler knowledge workflow','Email → investigation → validated resolution → reusable knowledge.')+`<div class="grid">${[['1 · Sign in','Use your username and password. Temporary passwords must be changed. Forgot your password? Use the reset link on the sign-in page to receive a recovery email.'],['2 · Choose a workspace','Inhouse, Enable, RPA and MATE remain separate. Other teams deploy independent copies.'],['3 · Add knowledge','Only Issue / Email / Extracted Content and Resolution are main fields. Environment/Server is optional.'],['4 · Import complete documents','Upload a file, choose Review extracted pairs, compare against the source and confirm the extraction. Resolutions are searchable on save; missing solutions remain unresolved. AI extraction is optional.'],['5 · Continue troubleshooting','Paste an email, attach images and ask follow-up questions in the same conversation. Validate evidence and outcomes.'],['6 · Govern access','Use Users and Admin for roles, workspace grants, AI settings, logo, security, audit and maintenance.']].map(x=>`<section class="card"><h2>${x[0]}</h2><p class="muted">${x[1]}</p></section>`).join('')}</div><section class="card"><h2>Extraction boundaries</h2><p class="muted">EML/MSG bodies and attachments are extracted. Inline CID images are mapped to protected local images where possible. Text PDFs and DOCX are supported with layout warnings. Scanned PDFs require separate OCR preprocessing. Image OCR requires Tesseract and OCR_ENABLED=true. Visual analysis requires an approved vision-capable model and enabled image input. Exact Outlook appearance is not guaranteed. Remote images and active content are removed.</p><p class="muted">Do not upload credentials or unapproved customer data. No production commands are executed. Review docs/SECURITY.md before production use.</p></section>`;}
function profile(){$('main').innerHTML=heading('YOUR ACCOUNT','Profile & preferences','Manage your display name, password and session.')+`<div class="grid"><section class="card"><h2>Profile</h2><label>Display name<input id="display-name" value="${esc(me.user.display_name)}"></label><p><span class="badge">${esc(me.user.role)}</span></p>${btn('profile-save','Save name',true)}</section><section class="card"><h2>Password & sessions</h2><p class="muted">Changing your password revokes all sessions. Password recovery is available by email if your account has a registered address; otherwise contact your administrator.</p>${btn('change-password','Change password')}</section></div>`;on('profile-save',async()=>{await api('/profile','PATCH',{display_name:$('display-name').value});await refreshMe();navigation();status('Profile updated.');});on('change-password',()=>passwordPage(false));}
(async()=>{try{await branding();const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken){resetPage(resetToken);return;}await refreshMe();await render();}catch{const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken){resetPage(resetToken);}else{login();}}})();

// Explicit user action only: prefill, allow correction, then use normal RBAC-protected save.
async function prepareAnswerCorrection(messageId){
    if(!has('knowledge.create'))throw Error('Knowledge creation permission required');
    const index=messages.findIndex(m=>m.id===messageId&&m.role==='assistant');
    if(index<0)throw Error('Answer not found in this conversation');
    const answer=messages[index];
    const prior=messages.slice(0,index).filter(m=>m.role==='user');
    const first=prior[0];
    const issueHtml=prior.map((m,i)=>'<h3>'+(i===0?'Original issue':'Follow-up context '+i)+'</h3>'+m.html).join('');
    const ids=[...new Set(prior.flatMap(m=>{try{return JSON.parse(m.assets||'[]');}catch{return [];}}))];
    files=ids.map(id=>({id,name:'Conversation attachment '+id.slice(0,8)}));
    editing=null;page='Add Knowledge';await render();
    $('issue').innerHTML=issueHtml||'<p>No issue context available; enter the issue before saving.</p>';
    $('resolution').innerHTML=esc(answer.text||'').replace(/\n/g,'<br>');
    status('Review and correct the proposed resolution, then Save knowledge. It becomes searchable immediately. This creates a new record; it does not silently overwrite source knowledge.');
}
